{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.Myntra_Sjit_fact_item as WITH sku_map AS ( SELECT \"myntra sku code\" AS myntra_sku_code, MAX(UPPER(TRIM(\"vendor article number\"))) AS sku FROM snitch_db.maplemonk.S3_MYNTRA_SJIT_SALES WHERE \"myntra sku code\" IS NOT NULL GROUP BY 1 ), sales AS ( SELECT \"seller order id\" AS seller_order_id, \"myntra sku code\" AS myntra_sku_code, MAX(UPPER(TRIM(\"vendor article number\"))) AS sku, MAX(REGEXP_REPLACE(UPPER(TRIM(\"vendor article number\")), \'-[^-]*$\', \'\')) AS sku_group, COALESCE(MAX(TRY_CAST(NULLIF(\"total mrp\", \'\') AS INT)), 0) AS mrp, COALESCE(MAX(TRY_CAST(NULLIF(\"final amount\", \'\') AS INT)), 0) AS sp, (COALESCE(MAX(TRY_CAST(NULLIF(\"total mrp\", \'\') AS INT)), 0) - COALESCE(MAX(TRY_CAST(NULLIF(\"final amount\", \'\') AS INT)), 0)) AS discount, MAX(TRY_TO_DATE(\"created on\", \'DD-MM-YYYY\')) AS order_date, SUM(TRY_CAST(NULLIF(\"IS_SHIP_REL\", \'\') AS INT)) AS total_quantity, ZIPCODE as PINCODE FROM snitch_db.maplemonk.S3_MYNTRA_SJIT_SALES WHERE TRY_CAST(NULLIF(\"IS_SHIP_REL\", \'\') AS INT) <> 0 GROUP BY \"seller order id\", \"myntra sku code\", ZIPCODE ) , returns AS ( SELECT r.\"SELLER_ORDER_ID\" AS seller_order_id, r.\"MYNTRA_SKU_CODE\" AS myntra_sku_code, s.sku, REGEXP_REPLACE(s.sku, \'-[^-]*$\', \'\') AS sku_group, MAX(r.\"STATUS\") AS return_status, SUM(r.\"QUANTITY\"::int) AS return_quantity, MAX(r.\"RETURN_REASON\") AS return_reason, MAX(CASE WHEN LOWER(r.\"RETURN_REASON\") LIKE \'%size%\' THEN \'Size & Fit Issue\' WHEN LOWER(r.\"RETURN_REASON\") LIKE \'%quality%\' THEN \'Quality Issue\' WHEN LOWER(r.\"RETURN_REASON\") LIKE \'%defect%\' THEN \'Quality Issue\' WHEN r.\"RETURN_REASON\" = \'Return Reason not found\' THEN \'Return Reason not found\' WHEN r.\"RETURN_REASON\" LIKE \'Miscellaneous%\' THEN \'Customer Changed Mind\' WHEN r.\"RETURN_REASON\" LIKE \'Order and Shipping Issues%\' THEN \'Order and Shipping Issues\' WHEN r.\"RETURN_REASON\" LIKE \'%Different%\' THEN \'Catalog Issues\' WHEN r.\"RETURN_REASON\" LIKE \'%image%\' THEN \'Catalog Image Issues\' ELSE \'Customer Changed Mind\' END) AS Reasons FROM snitch_db.maplemonk.S3_MYNTRA_SJIT_RETURNS r LEFT JOIN sku_map s ON r.\"MYNTRA_SKU_CODE\" = s.myntra_sku_code WHERE TRY_TO_DATE(TRIM(r.\"RETURN_CREATED_DATE\"), \'DD-MM-YYYY\') != \'1970-01-01\'::DATE GROUP BY r.\"SELLER_ORDER_ID\", r.\"MYNTRA_SKU_CODE\", s.sku ) , category_from_inv AS ( SELECT sku_group, category FROM snitch_db.maplemonk.Myntra_SJIT_INV_report WHERE sku_group IS NOT NULL AND category IS NOT NULL QUALIFY ROW_NUMBER() OVER(PARTITION BY sku_group ORDER BY date DESC) = 1 ), prod_details AS ( SELECT sku_group, product_name, sku_class, title, print_design, collar_new, material_new, fit, color, sleeve_type FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY status DESC) = 1 ) SELECT COALESCE(a.sku, b.sku) AS sku, COALESCE(a.sku_group, b.sku_group) AS sku_group, CASE WHEN COALESCE(a.sku, b.sku) LIKE \'%-%\' THEN SPLIT_PART(COALESCE(a.sku, b.sku), \'-\', ARRAY_SIZE(SPLIT(COALESCE(a.sku, b.sku), \'-\'))) ELSE NULL END AS size, a.sp, a.mrp, a.discount, COALESCE(a.seller_order_id, b.seller_order_id) AS seller_order_id, a.order_date, a.total_quantity, CASE WHEN b.return_quantity IS NOT NULL THEN a.order_date ELSE NULL END AS return_date, b.return_status, b.return_quantity, b.return_reason, b.Reasons AS categorized_return_reason, c.product_name, c.sku_class, cat.category, c.title, c.print_design, c.collar_new, c.material_new, c.fit, c.color, c.sleeve_type FROM sales a FULL OUTER JOIN returns b ON a.seller_order_id = b.seller_order_id AND a.myntra_sku_code = b.myntra_sku_code LEFT JOIN prod_details c ON COALESCE(a.sku_group, b.sku_group) = c.sku_group LEFT JOIN category_from_inv cat ON COALESCE(a.sku_group, b.sku_group) = cat.sku_group;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            